package com.kirox.app.security.shield

/** One signal the rules found: [reason] is short and lower-case («просят код входа»), [explain] is the «Почему?» text. */
data class ShieldSignal(val id: String, val weight: Double, val reason: String, val explain: String)

/**
 * Hand-written signals of the scam-text detector (RU / KZ / EN). Each one adds its weight to the logit in
 * [ShieldScorer]; several weak ones together are strong. Patterns run on [ShieldText.normalize]d text.
 */
object ShieldRules {
    private class Rule(val id: String, val weight: Double, val reason: String, val explain: String, val patterns: List<Regex>, val needs: List<Regex> = emptyList(), val unless: Regex? = null) {
        fun hit(t: String) = patterns.any { it.containsMatchIn(t) } && needs.all { it.containsMatchIn(t) } && unless?.containsMatchIn(t) != true
    }
    private fun r(vararg p: String) = p.map { rx(it) }

    /**
     * JVM (unit tests, JDK 19+) treats \w and \b as ASCII-only, Android's ICU as Unicode: spell both out so a
     * Cyrillic or Kazakh word behaves the same everywhere.
     */
    internal fun rx(p: String) = Regex(p.replace("\\w", "\\p{L}").replace("\\b", "(?:(?<![\\p{L}\\p{N}])|(?![\\p{L}\\p{N}]))"))

