    private const val PAY = """(переведи|переведите|перевести|перевод|скинь на карту|кинь на карту|на карту|номер карты|реквизит|оплат|оплати|предоплат|комисси|пошлин|залог|страховой взнос|ақша аудар|аудар|transfer|pay |payment|wire|deposit)"""

