    /** All signals that fire on [raw] (already normalised inside), strongest first. */
    fun signals(raw: String): List<ShieldSignal> {
        val t = ShieldText.normalize(raw)
        if (t.isBlank()) return emptyList()
        return RULES.filter { it.hit(t) }.map { ShieldSignal(it.id, it.weight, it.reason, it.explain) }.sortedByDescending { it.weight }
    }

    /** Ids of every rule, for the hub and tests. */
    val ids: List<String> get() = RULES.map { it.id }
}
